import React from 'react';

/* ─── SVG Icons (white, for orange circle) ─── */
const IconTicket = () => (
  <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
    <path d="M20 12V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v6"/>
    <path d="M4 12a2 2 0 0 1 0 4v2a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-2a2 2 0 0 1 0-4V12H4z"/>
    <line x1="9" y1="7" x2="9" y2="7.01"/>
    <line x1="12" y1="7" x2="12" y2="7.01"/>
    <line x1="15" y1="7" x2="15" y2="7.01"/>
  </svg>
);
const IconBriefcase = () => (
  <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
    <rect x="2" y="7" width="20" height="14" rx="2"/>
    <path d="M16 7V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v2"/>
    <line x1="12" y1="12" x2="12" y2="12"/>
    <path d="M2 12h20"/>
  </svg>
);
const IconUser = () => (
  <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
    <path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/>
    <circle cx="9" cy="7" r="4"/>
    <polyline points="16 11 18 13 22 9"/>
  </svg>
);
const IconChat = () => (
  <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
    <path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/>
    <line x1="9" y1="10" x2="9" y2="10.01"/>
    <line x1="12" y1="10" x2="12" y2="10.01"/>
    <line x1="15" y1="10" x2="15" y2="10.01"/>
  </svg>
);
const IconCamera = () => (
  <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
    <path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z"/>
    <circle cx="12" cy="13" r="4"/>
  </svg>
);
const IconCard = () => (
  <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
    <rect x="1" y="4" width="22" height="16" rx="2"/>
    <line x1="1" y1="10" x2="23" y2="10"/>
    <line x1="5" y1="15" x2="9" y2="15"/>
    <line x1="12" y1="15" x2="13" y2="15"/>
  </svg>
);

const features = [
  { Icon: IconTicket,    title: 'Billetterie simplifiée',    desc: "Achetez ou gérez vos tickets d'événements en toute simplicité. Chaque billet possède un QR code sécurisé pour un contrôle d'accès rapide et fiable." },
  { Icon: IconBriefcase, title: 'Réservation de services',   desc: "Trouvez et réservez les meilleurs prestataires pour vos événements : DJ, traiteurs, sécurité, salles, etc. Tout se fait en ligne, sans intermédiaire." },
  { Icon: IconUser,      title: 'Comptes hybrides',          desc: "Soyez à la fois organisateur et prestataire sur une seule plateforme. Créez vos événements tout en proposant vos services à d'autres." },
  { Icon: IconChat,      title: 'Dimension sociale',         desc: "Interagissez avec la communauté Djamano : commentez, notez, répondez et partagez vos expériences. Rendez chaque événement plus vivant et participatif." },
  { Icon: IconCamera,    title: 'Stories & promotions',      desc: "Publiez des stories temporaires pour promouvoir vos événements, services ou expériences. Un moyen simple de gagner en visibilité et de créer du lien." },
  { Icon: IconCard,      title: 'Paiements sécurisés',       desc: "Payez et recevez vos paiements via Mobile Money, cartes locales ou transferts bancaires. Des transactions rapides, sécurisées et adaptées à l'Afrique." },
];

const ServicesSection = () => {
  const s = {
    section: { background: '#fff', padding: '90px 32px', fontFamily: 'Poppins, sans-serif' },
    wrapper: { maxWidth: 1200, margin: '0 auto' },
    title: {
      fontSize: 34, fontWeight: 800, color: '#111',
      fontFamily: 'Poppins, sans-serif', letterSpacing: '-0.6px', marginBottom: 52,
    },
    orange: { color: '#FF5A00' },
    grid: { display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: '52px 32px' },
    card: {
      display: 'flex', flexDirection: 'column', alignItems: 'center',
      textAlign: 'center', gap: 0,
    },
    iconCircle: {
      width: 80, height: 80, borderRadius: '50%',
      background: '#FF5A00',
      display: 'flex', alignItems: 'center', justifyContent: 'center',
      marginBottom: 22, flexShrink: 0,
      boxShadow: '0 8px 28px rgba(255,90,0,.3)',
    },
    cardTitle: {
      fontSize: 17, fontWeight: 700, color: '#111',
      fontFamily: 'Poppins, sans-serif', marginBottom: 14,
    },
    cardDesc: {
      fontSize: 13.5, color: '#666', lineHeight: 1.75,
      fontFamily: 'Poppins, sans-serif', fontWeight: 400, maxWidth: 280,
    },
  };

  return (
    <section style={s.section}>
      <div style={s.wrapper}>
        <h2 style={s.title}>Qu'<span style={s.orange}>offrons</span> nous ?</h2>
        <div style={s.grid}>
          {features.map(({ Icon, title, desc }) => (
            <div key={title} style={s.card}>
              <div style={s.iconCircle}><Icon /></div>
              <div style={s.cardTitle}>{title}</div>
              <div style={s.cardDesc}>{desc}</div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default ServicesSection;
